const raw = $json.content?.parts?.[0]?.text || "";
let obj;
try {
  obj = JSON.parse(raw);
} catch (e1) {
  const cleaned = raw
    .replace(/```json\s*/i, "")
    .replace(/```/g, "")
    .trim();
  try {
    obj = JSON.parse(cleaned);
  } catch (e2) {
    throw new Error("Comms output not valid JSON. Raw: " + raw);
  }
}
return [{
  subject: obj.subject ?? "Service Request Confirmation",
  message: obj.body ?? obj.message ?? ""
}];
